import pathlib,csv,io,json,hashlib
root=pathlib.Path(__file__).resolve().parent
raw=(root/'len1_cond2_1.csv').read_bytes();assert hashlib.sha1(b'blob '+str(len(raw)).encode()+b'\0'+raw).hexdigest()=='795d0b31b09f1ba03d3182081938118e31727145'
rows=list(csv.DictReader(io.StringIO(raw.decode('utf-8-sig'))));selected=[(i,r)for i,r in enumerate(rows)if 5<=float(r['Time (s) Run #1'])<=25];assert len(selected)==2001
run={'id':'pasco-len1-cond2-1-new-condition','label':'New condition: same author length, air plus small paper baffle, repetition1','kind':'measured','dynamics':'unforced_scalar_rotation','inertia':None,'initialRate':float(selected[0][1]['Angular Velocity (rad/s) Run #1']),'source':{'label':'Xu et al., Damped Pendulum Dataset, original PASCO CSV','recordingId':'EnzeXu/Damped_Pendulum_Dataset/cbf82673641ecd65e902ad5c38a048387649a2a0/raw_data/len1_cond2_1.csv','repository':'https://github.com/EnzeXu/Damped_Pendulum_Dataset','revision':'cbf82673641ecd65e902ad5c38a048387649a2a0','license':'Apache-2.0','sha256':hashlib.sha256(raw).hexdigest(),'gitBlob':'795d0b31b09f1ba03d3182081938118e31727145','apparatus':'author length1 0.236m; condition2 air + small paper baffle; distinct recording','selection':{'firstRowZeroBased':selected[0][0],'lastRowZeroBased':selected[-1][0],'window':'Frozen5–25s inclusive, same existing intake rule','rawSampleCount':len(rows)},'transform':'No resampling, smoothing, recentering or time shift; supplied sensor velocity at first selected original row','role':'New held-back condition relative to this worker method development; not independently administered blind validation','uncertainty':'Unknown sensor-rate estimation/calibration and angle-zero comparability; no authenticated acquisition independence; no torque/inertia inferred'},'samples':[{'time':float(r['Time (s) Run #1']),'position':float(r['Angle (rad) Run #1'])}for _,r in selected]}
(root/'held-run.json').write_text(json.dumps(run,ensure_ascii=False,indent=2))
